// Original — Frictionborn Motion MagneticButton
"use client";

import React, { useRef, useState, useEffect, useCallback } from "react";
import { useFrame, useReducedMotion, useCapability, useHydrated } from "@frictionborn/runtime";

export interface MagneticButtonProps {
  children: React.ReactElement<{
    className?: string;
    style?: React.CSSProperties;
    onFocus?: React.FocusEventHandler;
    onBlur?: React.FocusEventHandler;
  }>;
  strength?: number;
  tension?: number;
  damping?: number;
  className?: string;
  style?: React.CSSProperties;
  maxTier?: number;
}

export function MagneticButton({
  children,
  strength = 16,
  tension = 180,
  damping = 16,
  className = "",
  style,
  maxTier = 3,
}: MagneticButtonProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const targetRef = useRef<{ x: number; y: number }>({ x: 0, y: 0 });
  const currentRef = useRef<{ x: number; y: number; vx: number; vy: number }>({
    x: 0,
    y: 0,
    vx: 0,
    vy: 0,
  });

  const hydrated = useHydrated();
  const prefersReduced = useReducedMotion();
  const { tier: rawTier } = useCapability();
  const tier = Math.min(rawTier, maxTier);

  const [isFinePointer, setIsFinePointer] = useState(false);
  const [isActive, setIsActive] = useState(false);

  // Gate pointer listeners strictly to fine pointers (hover: hover and pointer: fine)
  useEffect(() => {
    if (typeof window === "undefined") return;
    const mql = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsFinePointer(mql.matches);

    const handler = (e: MediaQueryListEvent) => setIsFinePointer(e.matches);
    mql.addEventListener("change", handler);
    return () => mql.removeEventListener("change", handler);
  }, []);

  const shouldEnable = hydrated && !prefersReduced && tier > 1 && isFinePointer;

  // Spring animation loop driven by shared useFrame
  useFrame(
    ({ dt }) => {
      const el = containerRef.current;
      if (!el) return;

      const deltaSec = Math.min(dt / 1000, 0.05);
      const cur = currentRef.current;
      const tgt = targetRef.current;

      // Spring physics (Hooke's law with damping)
      const ax = tension * (tgt.x - cur.x) - damping * cur.vx;
      const ay = tension * (tgt.y - cur.y) - damping * cur.vy;

      cur.vx += ax * deltaSec;
      cur.vy += ay * deltaSec;
      cur.x += cur.vx * deltaSec;
      cur.y += cur.vy * deltaSec;

      // Check settle condition
      const dx = Math.abs(tgt.x - cur.x);
      const dy = Math.abs(tgt.y - cur.y);
      const dv = Math.sqrt(cur.vx * cur.vx + cur.vy * cur.vy);

      if (dx < 0.01 && dy < 0.01 && dv < 0.01) {
        cur.x = tgt.x;
        cur.y = tgt.y;
        cur.vx = 0;
        cur.vy = 0;
        el.style.transform = tgt.x === 0 && tgt.y === 0 ? "" : `translate3d(${tgt.x}px, ${tgt.y}px, 0)`;
        setIsActive(false);
      } else {
        el.style.transform = `translate3d(${cur.x.toFixed(2)}px, ${cur.y.toFixed(2)}px, 0)`;
      }
    },
    { active: isActive && shouldEnable }
  );

  const handlePointerMove = useCallback(
    (e: React.PointerEvent) => {
      if (!shouldEnable || !containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const centerX = rect.left + rect.width / 2;
      const centerY = rect.top + rect.height / 2;

      const relX = (e.clientX - centerX) / (rect.width / 2);
      const relY = (e.clientY - centerY) / (rect.height / 2);

      targetRef.current = {
        x: Math.max(-strength, Math.min(strength, relX * strength)),
        y: Math.max(-strength, Math.min(strength, relY * strength)),
      };
      setIsActive(true);
    },
    [shouldEnable, strength]
  );

  const handlePointerLeave = useCallback(() => {
    if (!shouldEnable) return;
    targetRef.current = { x: 0, y: 0 };
    setIsActive(true);
  }, [shouldEnable]);

  // Keyboard focus resets position immediately to prevent disorienting keyboard users
  const handleFocus = useCallback(() => {
    targetRef.current = { x: 0, y: 0 };
    currentRef.current = { x: 0, y: 0, vx: 0, vy: 0 };
    if (containerRef.current) {
      containerRef.current.style.transform = "";
    }
    setIsActive(false);
  }, []);

  return (
    <div
      ref={containerRef}
      data-frictionborn-item="magnetic-button"
      data-tier={tier}
      className={`fb-magnetic-button ${className}`}
      onPointerMove={shouldEnable ? handlePointerMove : undefined}
      onPointerLeave={shouldEnable ? handlePointerLeave : undefined}
      style={{
        display: "inline-block",
        position: "relative",
        overflow: "visible", // Focus ring must never be clipped
        willChange: isActive ? "transform" : "auto",
        ...style,
      }}
    >
      {React.cloneElement(children, {
        onFocus: (e: React.FocusEvent) => {
          handleFocus();
          children.props.onFocus?.(e);
        },
      })}
    </div>
  );
}

export default MagneticButton;

// Original — Frictionborn Motion Marquee
"use client";

import React, { useRef, useState, useEffect } from "react";
import { useInView, useReducedMotion, useCapability, useHydrated, usePaused } from "@frictionborn/runtime";

export interface MarqueeProps {
  children: React.ReactNode;
  speed?: number;
  direction?: "left" | "right";
  pauseOnHover?: boolean;
  pauseOnFocus?: boolean;
  showPauseButton?: boolean;
  gap?: string | number;
  className?: string;
  style?: React.CSSProperties;
  maxTier?: number;
}

export function Marquee({
  children,
  speed = 40,
  direction = "left",
  pauseOnHover = true,
  pauseOnFocus = true,
  showPauseButton = true,
  gap = "2rem",
  className = "",
  style,
  maxTier = 3,
}: MarqueeProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const trackRef = useRef<HTMLDivElement>(null);

  const hydrated = useHydrated();
  const prefersReduced = useReducedMotion();
  const globalPaused = usePaused();
  const { tier: rawTier } = useCapability();
  const tier = Math.min(rawTier, maxTier);

  const [localPaused, setLocalPaused] = useState(false);
  const [duration, setDuration] = useState(25);

  const inView = useInView(containerRef as React.RefObject<HTMLElement>, {
    rootMargin: "100px",
  });

  // Calculate duration from track width and desired pixels/second
  useEffect(() => {
    if (!trackRef.current) return;
    const trackWidth = trackRef.current.scrollWidth;
    if (trackWidth > 0 && speed > 0) {
      setDuration(Math.max(5, trackWidth / speed));
    }
  }, [children, speed, gap]);

  const formattedGap = typeof gap === "number" ? `${gap}px` : gap;
  const isPaused = !inView || globalPaused || localPaused || prefersReduced || tier === 0;

  return (
    <div
      ref={containerRef}
      data-frictionborn-item="marquee"
      data-tier={tier}
      data-paused={isPaused ? "true" : undefined}
      className={`fb-marquee ${className}`}
      style={{
        position: "relative",
        width: "100%",
        overflow: "hidden",
        display: "flex",
        alignItems: "center",
        ...style,
      }}
    >
      <style>{`
        @keyframes fb-mq-slide-left {
          0% { transform: translateX(0%); }
          100% { transform: translateX(calc(-100% - var(--fb-mq-gap, 2rem))); }
        }

        @keyframes fb-mq-slide-right {
          0% { transform: translateX(calc(-100% - var(--fb-mq-gap, 2rem))); }
          100% { transform: translateX(0%); }
        }

        .fb-marquee-track {
          display: flex;
          flex-shrink: 0;
          align-items: center;
          gap: var(--fb-mq-gap, 2rem);
          will-change: transform;
        }

        [data-motion="ok"] .fb-marquee-track.anim-left {
          animation: fb-mq-slide-left var(--fb-mq-dur, 25s) linear infinite;
        }

        [data-motion="ok"] .fb-marquee-track.anim-right {
          animation: fb-mq-slide-right var(--fb-mq-dur, 25s) linear infinite;
        }

        .fb-marquee:hover [data-pause-hover="true"] .fb-marquee-track {
          animation-play-state: paused;
        }

        .fb-marquee:focus-within [data-pause-focus="true"] .fb-marquee-track {
          animation-play-state: paused;
        }

        .fb-marquee[data-paused="true"] .fb-marquee-track {
          animation-play-state: paused !important;
        }

        @media (prefers-reduced-motion: reduce) {
          .fb-marquee-track {
            animation: none !important;
          }
        }
      `}</style>

      {/* Marquee Viewport */}
      <div
        className="fb-marquee-viewport"
        style={{
          flex: 1,
          minWidth: 0,
          overflow: "hidden",
          display: "flex",
          alignItems: "center",
        }}
      >
        {/* Marquee Content Wrap */}
        <div
          data-pause-hover={pauseOnHover ? "true" : undefined}
          data-pause-focus={pauseOnFocus ? "true" : undefined}
          style={
            {
              display: "flex",
              width: "max-content",
              overflow: prefersReduced ? "auto" : "visible",
              "--fb-mq-gap": formattedGap,
              "--fb-mq-dur": `${duration}s`,
            } as React.CSSProperties
          }
        >
          {/* Original items (interactive, accessible to screen readers) */}
          <div
            ref={trackRef}
            className={`fb-marquee-track ${direction === "left" ? "anim-left" : "anim-right"}`}
            style={{ paddingRight: formattedGap }}
          >
            {children}
          </div>

          {/* Inert duplicate copy (aria-hidden and inert so screen readers & keyboard only visit items once) */}
          {(!prefersReduced && hydrated && tier > 0) && (
            <div
              aria-hidden="true"
              inert={true as any}
              className={`fb-marquee-track ${direction === "left" ? "anim-left" : "anim-right"}`}
            >
              {children}
            </div>
          )}
        </div>
      </div>

      {/* Accessible Pause/Play Toggle Button (WCAG 2.2.2) - positioned outside scrolling track */}
      {showPauseButton && hydrated && !prefersReduced && (
        <button
          type="button"
          onClick={() => setLocalPaused((p) => !p)}
          aria-label={localPaused ? "Play scrolling ticker" : "Pause scrolling ticker"}
          style={{
            flexShrink: 0,
            padding: "0.375rem 0.625rem",
            fontSize: "0.75rem",
            fontWeight: 500,
            borderRadius: "4px",
            border: "1px solid var(--border, currentColor)",
            background: "var(--background, transparent)",
            color: "var(--foreground, inherit)",
            cursor: "pointer",
            marginRight: "0.5rem",
          }}
        >
          {localPaused ? "Play" : "Pause"}
        </button>
      )}
    </div>
  );
}

export default Marquee;

// Original — Frictionborn Motion MeshGradient WebGL2 renderer
"use client";

import { useEffect, useRef, useCallback } from "react";
import { createSurface, type Surface } from "@frictionborn/runtime/gl";
import { useFrame, useFrameGuard, usePaused } from "@frictionborn/runtime";
import { vertexShaderSource, fragmentShaderSource } from "./mesh-gradient.glsl";

export interface MeshGradientGLProps {
  colors: [
    [number, number, number],
    [number, number, number],
    [number, number, number],
    [number, number, number]
  ];
  speed?: number;
  distortion?: number;
  swirl?: number;
  grainMixer?: number;
  grainOverlay?: number;
  tier?: number;
  paused?: boolean;
  reducedMotion?: boolean;
  suspended?: boolean;
  onDowngrade?: () => void;
  onContextLost?: () => void;
  onContextRestored?: () => void;
}

export default function MeshGradientGL({
  colors,
  speed = 0.35,
  distortion = 0.5,
  swirl = 0.25,
  grainMixer = 0.08,
  grainOverlay = 0.04,
  tier = 3,
  paused = false,
  reducedMotion = false,
  suspended = false,
  onDowngrade,
  onContextLost,
  onContextRestored,
}: MeshGradientGLProps) {
  const hostRef = useRef<HTMLDivElement | null>(null);
  const glSurface = useRef<Surface | null>(null);
  const glProgram = useRef<WebGLProgram | null>(null);
  const uniformMap = useRef<Map<string, WebGLUniformLocation>>(new Map());

  const elapsedClock = useRef(0);
  const activePalette = useRef(colors);
  activePalette.current = colors;

  const isGlobalPaused = usePaused();

  useFrameGuard({
    onDowngrade: onDowngrade ?? (() => {}),
    active: !paused && !isGlobalPaused && !reducedMotion && !suspended,
  }); // @frictionborn-guard

  const maxDpr = tier >= 3 ? 2.0 : 1.5;
  const meshScale = tier >= 3 ? 1.0 : 0.75;
  const meshOctaves = tier >= 3 ? 4 : 2;

  const lostHandler = useRef(onContextLost);
  lostHandler.current = onContextLost;
  const restoredHandler = useRef(onContextRestored);
  restoredHandler.current = onContextRestored;

  const flushMeshState = useCallback(
    (timeValue: number) => {
      const surface = glSurface.current;
      const prog = glProgram.current;
      if (!surface || !prog) return;

      const gl = surface.gl;
      const u = uniformMap.current;
      gl.useProgram(prog);

      const uRes = u.get("u_resolution");
      if (uRes) gl.uniform2f(uRes, gl.drawingBufferWidth, gl.drawingBufferHeight);

      const uTime = u.get("u_time");
      if (uTime) gl.uniform1f(uTime, timeValue);

      const uSpeed = u.get("u_speed");
      if (uSpeed) gl.uniform1f(uSpeed, speed);

      const uDistort = u.get("u_distortion");
      if (uDistort) gl.uniform1f(uDistort, distortion);

      const uSwirl = u.get("u_swirl");
      if (uSwirl) gl.uniform1f(uSwirl, swirl);

      const uMixer = u.get("u_grain_mixer");
      if (uMixer) gl.uniform1f(uMixer, grainMixer);

      const uOverlay = u.get("u_grain_overlay");
      if (uOverlay) gl.uniform1f(uOverlay, grainOverlay);

      const uOct = u.get("u_octaves");
      if (uOct) gl.uniform1i(uOct, meshOctaves);

      const pal = activePalette.current;
      for (let i = 0; i < 4; i++) {
        const uCol = u.get(`u_color${i}`);
        if (uCol) {
          gl.uniform3f(uCol, pal[i][0], pal[i][1], pal[i][2]);
        }
      }

      surface.draw();
    },
    [speed, distortion, swirl, grainMixer, grainOverlay, meshOctaves]
  );

  useEffect(() => {
    const parent = hostRef.current;
    if (!parent) return;

    const cvs = document.createElement("canvas");
    cvs.setAttribute("aria-hidden", "true");
    cvs.setAttribute("data-frictionborn-gl", "mesh-gradient");
    Object.assign(cvs.style, {
      position: "absolute",
      inset: "0",
      width: "100%",
      height: "100%",
      display: "block",
      pointerEvents: "none",
      zIndex: "2",
    });
    parent.appendChild(cvs);

    const initShaders = (s: Surface) => {
      const gl = s.gl;
      const prog = s.createProgram(vertexShaderSource, fragmentShaderSource);
      glProgram.current = prog;

      const map = new Map<string, WebGLUniformLocation>();
      const names = [
        "u_resolution",
        "u_time",
        "u_speed",
        "u_distortion",
        "u_swirl",
        "u_grain_mixer",
        "u_grain_overlay",
        "u_octaves",
        "u_color0",
        "u_color1",
        "u_color2",
        "u_color3",
      ];
      for (const name of names) {
        const loc = gl.getUniformLocation(prog, name);
        if (loc) map.set(name, loc);
      }
      uniformMap.current = map;
    };

    try {
      const surface = createSurface(cvs, {
        maxDpr,
        scale: meshScale,
        onContextLost: () => {
          cvs.style.display = "none";
          lostHandler.current?.();
        },
        onContextRestored: () => {
          cvs.style.display = "block";
          if (glSurface.current) {
            glSurface.current.resize();
            initShaders(glSurface.current);
            flushMeshState(elapsedClock.current);
          }
          restoredHandler.current?.();
        },
      }); // @frictionborn-guard

      glSurface.current = surface;
      initShaders(surface);
      flushMeshState(elapsedClock.current);
    } catch (failure) {
      console.warn("MeshGradient WebGL2 surface failure", failure);
      if (glSurface.current) {
        glSurface.current.dispose(); // @frictionborn-guard
        glSurface.current = null;
      }
      lostHandler.current?.();
    }

    return () => {
      if (glSurface.current) {
        glSurface.current.dispose(); // @frictionborn-guard
        glSurface.current = null;
      }
      cvs.remove();
    };
  }, [maxDpr, meshScale, flushMeshState]);

  useFrame(
    ({ dt }) => {
      elapsedClock.current += (dt * 0.001) * speed;
      flushMeshState(elapsedClock.current);
    },
    { active: !paused && !isGlobalPaused && !reducedMotion && !suspended } // @frictionborn-guard
  );

  return (
    <div
      ref={hostRef}
      aria-hidden="true"
      className="fb-mesh-surface"
      style={{
        position: "absolute",
        inset: 0,
        width: "100%",
        height: "100%",
        overflow: "hidden",
        pointerEvents: "none",
        zIndex: 2,
        visibility: suspended ? "hidden" : "visible",
      }}
    />
  );
}

// Source: https://github.com/stegu/webgl-noise — MIT — Copyright (C) 2011 Ashima Arts, Stefan Gustavson
// Adaptation & composition: Original — Frictionborn Motion

export const vertexShaderSource = `#version 300 es
in vec2 position;
out vec2 v_uv;

void main() {
  v_uv = (position + 1.0) * 0.5;
  gl_Position = vec4(position, 0.0, 1.0);
}
`;

export const fragmentShaderSource = `#version 300 es
precision highp float;

in vec2 v_uv;
out vec4 fragColor;

uniform vec2 u_resolution;
uniform float u_time;
uniform float u_speed;
uniform float u_distortion;
uniform float u_swirl;
uniform float u_grain_mixer;
uniform float u_grain_overlay;
uniform int u_octaves;

uniform vec3 u_color0;
uniform vec3 u_color1;
uniform vec3 u_color2;
uniform vec3 u_color3;

// --- Stefan Gustavson / Ashima Arts 2D Simplex Noise (MIT License) ---
vec3 mod289(vec3 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec2 mod289(vec2 x) {
  return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec3 permute(vec3 x) {
  return mod289(((x * 34.0) + 1.0) * x);
}

float snoise(vec2 v) {
  const vec4 C = vec4(
    0.211324865405187,   // (3.0 - sqrt(3.0)) / 6.0
    0.366025403784439,   // 0.5 * (sqrt(3.0) - 1.0)
   -0.577350269189626,   // -1.0 + 2.0 * C.x
    0.024390243902439    // 1.0 / 41.0
  );

  vec2 i  = floor(v + dot(v, C.yy));
  vec2 x0 = v - i + dot(i, C.xx);

  vec2 i1 = (x0.x > x0.y) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
  vec4 x12 = x0.xyxy + C.xxzz;
  x12.xy -= i1;

  i = mod289(i);
  vec3 p = permute(permute(i.y + vec3(0.0, i1.y, 1.0)) + i.x + vec3(0.0, i1.x, 1.0));

  vec3 m = max(0.5 - vec3(dot(x0, x0), dot(x12.xy, x12.xy), dot(x12.zw, x12.zw)), 0.0);
  m = m * m;
  m = m * m;

  vec3 x = 2.0 * fract(p * C.www) - 1.0;
  vec3 h = abs(x) - 0.5;
  vec3 ox = floor(x + 0.5);
  vec3 a0 = x - ox;

  m *= 1.79284291400159 - 0.85373472095314 * (a0 * a0 + h * h);

  vec3 g;
  g.x  = a0.x  * x0.x  + h.x  * x0.y;
  g.yz = a0.yz * x12.xz + h.yz * x12.yw;
  return 130.0 * dot(m, g);
}
// --- End simplex noise primitive ---

// Original Frictionborn organic mesh-gradient composition
void main() {
  vec2 p = v_uv;

  // 1. Swirl distortion around center
  vec2 center = vec2(0.5, 0.5);
  vec2 d = p - center;
  float r = length(d);
  float theta = atan(d.y, d.x);
  float swirlEffect = u_swirl * sin(r * 4.0 - u_time * 0.4);
  vec2 pSwirl = center + vec2(cos(theta + swirlEffect), sin(theta + swirlEffect)) * r;

  // 2. Domain-warping with simplex noise
  vec2 warp = vec2(
    snoise(pSwirl * 2.2 + vec2(u_time * 0.15, -u_time * 0.10)),
    snoise(pSwirl * 2.2 + vec2(-u_time * 0.12, u_time * 0.18))
  );
  vec2 pWarped = pSwirl + warp * (u_distortion * 0.28);

  if (u_octaves >= 3) {
    vec2 warpFine = vec2(
      snoise(pWarped * 4.4 + vec2(-u_time * 0.20, u_time * 0.25)),
      snoise(pWarped * 4.4 + vec2(u_time * 0.22, -u_time * 0.15))
    );
    pWarped += warpFine * (u_distortion * 0.12);
  }

  // 3. Dynamic color anchor centers (matching CSS poster positions at rest)
  vec2 a1 = vec2(0.20, 0.30) + vec2(0.08 * sin(u_time * 0.35), 0.06 * cos(u_time * 0.45));
  vec2 a2 = vec2(0.80, 0.70) + vec2(0.07 * cos(u_time * 0.40), 0.08 * sin(u_time * 0.30));
  vec2 a3 = vec2(0.50, 0.50) + vec2(0.06 * sin(u_time * 0.50), 0.07 * cos(u_time * 0.35));

  // 4. Weight interpolation
  float d1 = distance(pWarped, a1);
  float w1 = smoothstep(0.65, 0.0, d1) * 0.75;

  float d2 = distance(pWarped, a2);
  float w2 = smoothstep(0.60, 0.0, d2) * 0.70;

  float d3 = distance(pWarped, a3);
  float w3 = smoothstep(0.70, 0.0, d3) * 0.80;

  // 5. Blending with base color
  vec3 col = u_color0;
  col = mix(col, u_color1, w1);
  col = mix(col, u_color2, w2);
  col = mix(col, u_color3, w3);

  // 6. Subtle grain overlay / dither to eliminate banding
  float noise = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453) - 0.5;
  float grain = noise * (u_grain_mixer * 0.3 + u_grain_overlay * 0.7);
  col += grain;

  fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
`;

// Original — Frictionborn Motion MeshGradient
"use client";

import React, { useState, useEffect, useRef, useCallback, Suspense, lazy } from "react";
import {
  useCapability,
  useHydrated,
  useReducedMotion,
  useInView,
  resolveCssColor,
  glBudget,
  type Lease,
} from "@frictionborn/runtime";

const MeshGradientGL = lazy(() => import("./mesh-gradient.gl"));

export interface MeshGradientProps extends React.HTMLAttributes<HTMLDivElement> {
  colors?: string[];
  speed?: number;
  distortion?: number;
  swirl?: number;
  grainMixer?: number;
  grainOverlay?: number;
  scrim?: boolean;
  paused?: boolean;
  maxTier?: number;
  reducedMotion?: boolean;
  children?: React.ReactNode;
}

// Host tokens with CSS system-colour fallbacks; stable module-level constant
const DEFAULT_MESH_TOKENS = [
  "var(--background, Canvas)",
  "var(--primary, CanvasText)",
  "var(--chart-1, var(--accent, GrayText))",
  "var(--chart-2, var(--muted, ButtonFace))",
];

type RgbTriple = [number, number, number];
const DEFAULT_RGB_QUAD: [RgbTriple, RgbTriple, RgbTriple, RgbTriple] = [
  [0.05, 0.06, 0.08],
  [0.22, 0.74, 0.97],
  [0.51, 0.55, 0.97],
  [0.12, 0.16, 0.23],
];

export function MeshGradient({
  colors = DEFAULT_MESH_TOKENS,
  speed = 0.35,
  distortion = 0.5,
  swirl = 0.25,
  grainMixer = 0.08,
  grainOverlay = 0.04,
  scrim = false,
  paused = false,
  maxTier = 3,
  reducedMotion: propReduced,
  className = "",
  style,
  children,
  ...props
}: MeshGradientProps) {
  const hostElementRef = useRef<HTMLDivElement | null>(null);
  const isClientHydrated = useHydrated(); // @frictionborn-guard
  const runtimeCap = useCapability(); // @frictionborn-guard
  const prefersReduce = useReducedMotion(); // @frictionborn-guard
  const suppressMotion = propReduced !== undefined ? propReduced : prefersReduce; // @frictionborn-guard
  const isInViewport = useInView(hostElementRef); // @frictionborn-guard

  const [hasContextLease, setHasContextLease] = useState(false);
  const leaseHandle = useRef<Lease | null>(null);
  const instanceTag = useRef(`mesh-${Math.random().toString(36).slice(2, 9)}`);
  const [contextSevered, setContextSevered] = useState(false);

  const [effectiveTier, setEffectiveTier] = useState<number>(0);
  const [activeColors, setActiveColors] = useState<[RgbTriple, RgbTriple, RgbTriple, RgbTriple]>(DEFAULT_RGB_QUAD);

  const refreshColors = useCallback(() => {
    const el = hostElementRef.current;
    const resolved: RgbTriple[] = colors.map((c) => {
      const rgb = resolveCssColor(el, c);
      return rgb ? (rgb as RgbTriple) : [0.5, 0.5, 0.5];
    });

    const c0 = resolved[0] ?? DEFAULT_RGB_QUAD[0];
    const c1 = resolved[1] ?? resolved[0] ?? DEFAULT_RGB_QUAD[1];
    const c2 = resolved[2] ?? resolved[1] ?? DEFAULT_RGB_QUAD[2];
    const c3 = resolved[3] ?? resolved[0] ?? DEFAULT_RGB_QUAD[3];
    const next: [RgbTriple, RgbTriple, RgbTriple, RgbTriple] = [c0, c1, c2, c3];

    setActiveColors((prev) => {
      const isIdentical =
        prev.length === 4 &&
        prev.every(
          (tuple, i) =>
            Math.abs(tuple[0] - next[i][0]) < 0.002 &&
            Math.abs(tuple[1] - next[i][1]) < 0.002 &&
            Math.abs(tuple[2] - next[i][2]) < 0.002
        );
      return isIdentical ? prev : next;
    });
  }, [colors]);

  useEffect(() => {
    refreshColors();
    if (typeof MutationObserver === "undefined") return;
    const obs = new MutationObserver(refreshColors);
    obs.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "data-theme", "data-mode", "style"],
    });
    return () => obs.disconnect();
  }, [refreshColors]);

  useEffect(() => {
    if (isClientHydrated) {
      setEffectiveTier(Math.min(runtimeCap.tier, maxTier));
    }
  }, [isClientHydrated, runtimeCap.tier, maxTier]);

