  "var(--background, Canvas)",
  "var(--primary, CanvasText)",
  "var(--accent, GrayText)",
];

export function NoiseField({
  colors = DEFAULT_COLORS,
  speed = 1.0,
  scale = 1.8,
  intensity = 1.0,
  scrim = true,
  paused = false,
  time,
  maxTier = 3,
  reducedMotion: propReduced,
  className = "",
  style,
  children,
  ...props
}: NoiseFieldProps) {
